    // Dimension 0 (x) = column j, extent m
    // Dimension 1 (y) = row i, extent n
    ImageParam data_param(type_of<num_t>(), 2, "data_param");
    data_param.set(data);

    // Halide Vars and reduction domains
    Var i("i"), j("j");
    Var p("p"), q("q");    // indices over columns for covariance
    RDom r_i(0, data_param.dim(1).extent(), "r_i"); // rows for mean
    RDom r_k(0, data_param.dim(1).extent(), "r_k"); // rows for covariance

    // float_n as a Halide expression constant
    Expr float_n_expr = cast<num_t>(float_n);

    // ------------------------------------------------------------------
    // 1. Compute column means:
    //
    // for (j = 0; j < M; j++) {
    //   mean[j] = 0;
    //   for (i = 0; i < N; i++)
