    // }
    // ------------------------------------------------------------------

    Func mean_sum("mean_sum");
    mean_sum(j) = cast<num_t>(0);
    mean_sum(j) += data_param(j, r_i);

    Func mean("mean");
    mean(j) = mean_sum(j) / float_n_expr;

    // ------------------------------------------------------------------
    // 2. Center the data by subtracting the mean from each column:
    //
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < M; j++)
    //     data[i][j] -= mean[j];
    //
    // We don't modify the input buffer; instead we define a new Func.
    // ------------------------------------------------------------------

    Func data_centered("data_centered");
    data_centered(j, i) = data_param(j, i) - mean(j);

