#include "covariance.hpp"

using num_t = DATA_TYPE;

using namespace Halide;


/* Array initialization. */
static
void init_array(int m, int n,
                num_t *float_n,
                Halide::Buffer<num_t, 2> data) {
    // C code:
    // *float_n = (DATA_TYPE)n;
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < M; j++)
    //     data[i][j] = ((DATA_TYPE) i*j) / M;

    *float_n = (num_t)n;

    Var i("i"), j("j");
    Func init_data("init_data");

    // data is sized as data(m, n) with access data(j, i) == data[i][j] in C.
    // i in [0, n), j in [0, m)
    Expr num = cast<num_t>(i) * cast<num_t>(j);
    Expr denom = cast<num_t>(m);
    init_data(j, i) = num / denom;

    init_data.realize(data);
}

int main(int argc, char *argv[]) {
    // Problem size (Polybench style)
    int n = N; // number of observations (rows)
    int m = M; // number of variables (columns)

    // Variables corresponding to C scalars/arrays
    num_t float_n;
    // C layout: data[N][M] -> Buffer(m, n) with access data(j, i) == data[i][j]
    Halide::Buffer<num_t, 2> data(m, n);
    // C layout: cov[M][M] -> Buffer(m, m) with access cov(j, i) == cov[i][j]
    Halide::Buffer<num_t, 2> cov(m, m);

    // Initialize arrays (same semantics as C init_array)
    init_array(m, n, &float_n, data);

    // Halide pipeline --------------------------------------------------------

    // ImageParam for input data
    ImageParam data_param(type_of<num_t>(), 2, "data_param");
    // Scalar Param for float_n
    Param<num_t> float_n_param("float_n_param");

    // Vars
    Var j("j"), i("i");      // j: column (0..m-1), i: row (0..n-1)
    Var p("p"), q("q");      // indices for covariance matrix

    // 1) Compute column means: mean[j] = (1/float_n) * sum_i data[i][j]
    Func mean("mean");
    {
        // Reduction over rows (i dimension, which is dim(1))
        RDom ri(0, data_param.dim(1).extent(), "ri");
        // mean has one dimension (columns)
        mean(j) = sum(data_param(j, ri)) / float_n_param;
    }

    // 2) Center the data: centered[i][j] = data[i][j] - mean[j]
    //    In our Buffers: centered(j, i) = data_param(j, i) - mean(j)
    Func centered("centered");
    centered(j, i) = data_param(j, i) - mean(j);

    // 3) Covariance:
    //    cov[i][j] = sum_k centered[k][i] * centered[k][j] / (float_n - 1)
    // We compute the full symmetric matrix (both upper and lower parts);
    // entries will be identical to the C code's result.
    Func cov_func("covariance");
    {
        RDom rk(0, data_param.dim(1).extent(), "rk"); // k over rows N
        Expr denom = float_n_param - (num_t)1.0;

        // p and q range over columns [0, m)
        cov_func(p, q) = sum(centered(p, rk) * centered(q, rk)) / denom;
    }

    // Simple schedule mirroring the logical structure
    mean.compute_root();
    centered.compute_root();
    cov_func.compute_root();

    // Bind parameters
    data_param.set(data);
    float_n_param.set(float_n);

    // Compile the kernel to machine code (JIT)
    cov_func.compile_jit();

    // Measure execution time of the kernel (as Polybench does for kernel_covariance)
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: compute covariance matrix into cov
    cov_func.realize(cov);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional result printing (to prevent dead-code elimination and for checking)
    // Print if any extra argument is given
    if (argc > 1) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i_idx = 0; i_idx < m; i_idx++) {
            for (int j_idx = 0; j_idx < m; j_idx++) {
                // cov[i][j] in C == cov(j, i) here
                std::cerr << cov(j_idx, i_idx) << '\n';
            }
        }
    }

    // Print execution time in seconds (similar role to Polybench timers)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
