    // i is the row index (0..n-1), j is the column index (0..m-1).
    init_data(j, i) = cast<num_t>(i * j) / cast<int>(m);

    // Realize over the actual buffer extents.
    init_data.realize(data);
}

int main(int argc, char *argv[]) {
    // Problem size (matching the original C code)
    int n = N;  // number of rows (observations)
    int m = M;  // number of columns (variables)

    // Host-side data
    num_t float_n;

    // Buffers:
    // Original C:
    //   DATA_TYPE data[N][M];
    //   DATA_TYPE cov[M][M];
    //
    // We map data[i][j] -> data(j, i) in Halide, so:
    //   data has width = M (columns), height = N (rows)
    //
    // cov[i][j] -> cov(j, i), so:
    //   cov has width = M, height = M
    Halide::Buffer<num_t, 2> data(m, n);
    Halide::Buffer<num_t, 2> cov(m, m);

    // Initialize input array
    init_array(m, n, &float_n, data);

    // -----------------------------------------------------------------
    // Build the Halide pipeline for kernel_covariance
    // -----------------------------------------------------------------

    // ImageParam for the input data array
    ImageParam data_param(type_of<num_t>(), 2, "data_param");

    // Scalar Param for float_n
    Param<num_t> float_n_param("float_n_param");

    // Bind runtime data to Halide parameters
    data_param.set(data);
    float_n_param.set(float_n);

    // Vars
    Var i("i"), j("j");
    Var row("row"), col("col");
    Var col1("col1"), col2("col2");

    // -----------------------------------------------------------------
    // mean[j] = sum_i data[i][j] / float_n;
    // -----------------------------------------------------------------
    Func mean_sum("mean_sum");
    Func mean("mean");

    // Reduction domain over rows (i = 0..n-1)
    RDom r_mean(0, data_param.dim(1).extent(), "r_mean");

    // Accumulate column sums
    mean_sum(j) = cast<num_t>(0);
    mean_sum(j) += data_param(j, r_mean);

    // Normalize by float_n
    mean(j) = mean_sum(j) / float_n_param;

    // -----------------------------------------------------------------
    // Centered data: data_centered[i][j] = data[i][j] - mean[j];
    // In Halide: centered(col, row) = data_param(col, row) - mean(col);
    // -----------------------------------------------------------------
    Func centered("centered");
    centered(col, row) = data_param(col, row) - mean(col);

    // -----------------------------------------------------------------
    // Covariance:
    //
    // C code:
    //   for (i = 0; i < M; i++)
    //     for (j = i; j < M; j++) {
    //       cov[i][j] = 0;
    //       for (k = 0; k < N; k++)
    //         cov[i][j] += data[k][i] * data[k][j];
    //       cov[i][j] /= (float_n - 1.0);
    //       cov[j][i] = cov[i][j];
    //     }
    //
    // We compute full covariance matrix (all i,j), which is
    // mathematically equivalent and yields a symmetric matrix.
    //
    // cov(col1, col2) = sum_k centered(col1, k) * centered(col2, k)
    //                     / (float_n - 1)
    // -----------------------------------------------------------------
    Func cov_accum("cov_accum");
    Func cov_final("cov_final");

    // Reduction domain over rows (k = 0..n-1)
    RDom r_cov(0, data_param.dim(1).extent(), "r_cov");

    cov_accum(col1, col2) = cast<num_t>(0);
    cov_accum(col1, col2) += centered(col1, r_cov) * centered(col2, r_cov);

    cov_final(col1, col2) =
        cov_accum(col1, col2) / (float_n_param - cast<num_t>(1));

    // Simple schedules to match the logical C loop ordering
    mean_sum.reorder(j);
    mean_sum.update().reorder(j, r_mean);

    cov_accum.reorder(col1, col2);
    cov_accum.update().reorder(col1, r_cov, col2);

    cov_final.reorder(col1, col2);

    // Compile the kernel
    cov_final.compile_jit();

    // -----------------------------------------------------------------
    // Run and time the kernel
    // -----------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    cov_final.realize(cov);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -----------------------------------------------------------------
    // Optionally print the resulting covariance matrix
    // (similar to print_array in the original C code)
    // -----------------------------------------------------------------
    using namespace std::string_literals;

    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i_idx = 0; i_idx < m; i_idx++) {
            for (int j_idx = 0; j_idx < m; j_idx++) {
                // cov[i][j] in C corresponds to cov(j, i) in Halide
                std::cerr << cov(j_idx, i_idx) << '\n';
            }
        }
    }

    // Print timing in seconds (like gemm example)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
